  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,       // deletion
        dp[i][j - 1] + 1,       // insertion
        dp[i - 1][j - 1] + cost  // substitution
      );
    }
  }

  return dp[m][n];
}

/**
 * Create a debug helper for KnockoutJS binding errors.
 * @param {Object} viewModel - The ViewModel object
 * @returns {Object} A debug helper object with diagnoseMissingProperty method
 */
function createDebugHelper(viewModel) {
  return {
    /**
     * Diagnose a missing property in a binding.
     * @param {string} propertyName - The name of the property that failed to bind
     * @returns {Object} Diagnostic result object
     */
    diagnoseMissingProperty(propertyName) {
      // Get all own property names from the viewModel
      const availableProperties = Object.keys(viewModel).sort();

      // Find the closest matching property using Levenshtein distance
      let suggestion = null;
      let minDistance = Infinity;

      for (const prop of availableProperties) {
        const distance = levenshteinDistance(propertyName, prop);
        if (distance <= 3) {
          if (distance < minDistance || (distance === minDistance && prop < suggestion)) {
            minDistance = distance;
            suggestion = prop;
          }
        }
      }

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: suggestion
      };
    }
  };
}

module.exports = { createDebugHelper };
